// ------------------------------------------
// READ WEBHOOK BODY SAFELY
// ------------------------------------------

let body = $json.body ?? $json;

// If n8n supplies the body as a JSON string,
// convert it back into an object.
if (typeof body === "string") {
    try {
        body = JSON.parse(body);
    } catch (error) {
        throw new Error("Webhook body is not valid JSON.");
    }
}

// ------------------------------------------
// ALLOWED GOVERNANCE DECISIONS
// ------------------------------------------

const allowedDecisions = [
    "Approved",
    "Approved with Conditions",
    "Rejected",
    "Request More Information"
];

// ------------------------------------------
// NORMALIZE INPUT
// ------------------------------------------

const changeRequestId = Number(body.change_request_id);

const assessmentId =
    body.assessment_id === null ||
    body.assessment_id === undefined ||
    body.assessment_id === ""
        ? null
        : Number(body.assessment_id);

const decision =
    typeof body.decision === "string"
        ? body.decision.trim()
        : "";

const decisionComments =
    typeof body.decision_comments === "string"
        ? body.decision_comments.trim()
        : "";

const conditions =
    typeof body.conditions === "string"
        ? body.conditions.trim()
        : "";

const decidedBy =
    typeof body.decided_by === "string"
        ? body.decided_by.trim()
        : "";

// ------------------------------------------
// VALIDATION
// ------------------------------------------

if (
    !Number.isInteger(changeRequestId) ||
    changeRequestId <= 0
) {
    throw new Error(
        `change_request_id must be a valid positive integer. Received: ${body.change_request_id}`
    );
}

if (
    assessmentId !== null &&
    (
        !Number.isInteger(assessmentId) ||
        assessmentId <= 0
    )
) {
    throw new Error(
        `assessment_id must be a valid positive integer or null. Received: ${body.assessment_id}`
    );
}

if (!allowedDecisions.includes(decision)) {
    throw new Error(
        `Invalid decision '${decision}'. Allowed values: ${allowedDecisions.join(", ")}`
    );
}

if (!decidedBy) {
    throw new Error(
        "decided_by is required."
    );
}

if (
    decision === "Approved with Conditions" &&
    !conditions
) {
    throw new Error(
        "conditions are required when decision is Approved with Conditions."
    );
}

// ------------------------------------------
// OUTPUT
// ------------------------------------------

return [
    {
        json: {
            change_request_id: changeRequestId,
            assessment_id: assessmentId,
            decision,
            decision_comments: decisionComments || null,
            conditions: conditions || null,
            decided_by: decidedBy,
            validation_status: "VALID"
        }
    }
];
